alter policy listings_public_read on public.companion_listings to anon;
create policy listings_authenticated_read on public.companion_listings for select to authenticated using (published and moderation_status='active' or (select auth.uid())=user_id or exists(select 1 from public.platform_admins a where a.user_id=(select auth.uid())));
drop policy listings_admin_read on public.companion_listings;
drop policy listings_owner_read on public.companion_listings;
create policy listings_authenticated_update on public.companion_listings for update to authenticated using ((select auth.uid())=user_id or exists(select 1 from public.platform_admins a where a.user_id=(select auth.uid()))) with check (((select auth.uid())=user_id and (not published or exists(select 1 from public.member_profiles p where p.user_id=(select auth.uid()) and p.profile_kind in ('companion','both')))) or exists(select 1 from public.platform_admins a where a.user_id=(select auth.uid())));
drop policy listings_admin_update on public.companion_listings;
drop policy listings_owner_update on public.companion_listings;
create policy profile_authenticated_read on public.member_profiles for select to authenticated using ((select auth.uid())=user_id or exists(select 1 from public.platform_admins a where a.user_id=(select auth.uid())));
drop policy profile_admin_read on public.member_profiles;
drop policy profile_read_own on public.member_profiles;
notify pgrst, 'reload schema';
